const TB = t => [t,'REALCHECK-843','localization-fixes-nov-2026'];
const PLAN = {}; const put = (n, tags, desc) => { PLAN[id(n)] = { tags: tags, desc: desc }; };
const POP1 = "Deep search pop-up 1 (reason picker) – opens 3 seconds after a paid phone lookup report loads and asks why the customer is checking the number. ";
const E19 = " Ticket: REALCHECK-819.";
put(9, T819, POP1 + "Small badge above the title, in capitals by design. 'FREE' = at no extra cost (adjective, not 'free time' or 'set free'); the deep search is included in the report the customer already paid for. '·' is only a separator." + E19);
