put(20, T819, "Deep search pop-up 2 (confirmation) – shown after the customer picks a reason and presses 'Get my personalised report'. TITLE. 'summary' = the deep search summary text that will appear in the report." + E19);
put(21, T819, "Deep search pop-up 2 (confirmation) – text under the title. 'It' = the summary. The customer's account email address is shown right after this text, on the next line (the sentence ends with 'at' + email), so the sentence must end where the email can follow." + E19);
put(22, T819, "Deep search pop-up 2 (confirmation) – note about how long the deep search takes. Keep <b> and </b> (bold) and the numbers 20 and 2." + E19);
put(23, T819, "Deep search pop-up 2 (confirmation) – the only BUTTON; closes the pop-up and returns to the report. 'Got it' = OK / understood (acknowledgement), not 'I received it'. Keep it short." + E19);
put(8, T819, "Phone lookup report – TITLE of the new 'Report insights' section at the top of the report (above Profile summary), where the deep search summary appears. Same text as chapters::deep_search (its item in the report's 'Content' list): use the same translation for both." + E19);
put(7, T819, "Phone lookup report – item in the 'Content' list (table of contents) that links to the 'Report insights' section. Same text as deep_search::title: use the same translation for both." + E19);
put(24, T819, "Phone lookup report, 'Report insights' section – heading above the progress bar shown while the deep search summary is being prepared (noun phrase: the summary is being prepared)." + E19);
put(30, T819, "Phone lookup report, 'Report insights' section – grey note under the finished summary, shown for every reason. Legal disclaimer: keep 'Fair Credit Reporting Act (FCRA)' as the name of the US law. 'consumer report' is the legal term from that law (a credit/background report)." + E19);
put(31, T819, "Phone lookup report – BUTTON in the report that opens the deep search reason picker (Flow B, REALCHECK-820). 'Deep search' is the feature name used as a button label: the button starts a deep (more thorough) search/analysis of the report. Keep it short." + E19);
['0–19%','20–39%','40–59%','60–79%','80–99%'].forEach((r, i) => put(25 + i, T819, "Phone lookup report, 'Report insights' section – line under the progress bar while the summary is prepared, shown at " + r + ". The line changes every 20% (step_1 to step_5); full sentence with final full stop." + E19));
const OPT = POP1 + "One of 7 answer OPTIONS (single choice) to 'why are you checking this number'. Written from the customer's side ('me', 'I'), like the customer is speaking. The summary is then written for this reason.";
// reasons 819: caller 12, scam 13, online 14, identity 15, reconnect 16, deal 17, general 18
[12,13,15,16,18].forEach(n => put(n, T819, OPT + E19));
put(14, T819, OPT + " 'someone I met online' = e.g. on a dating app or social network." + E19);
put(17, T819, OPT + " 'deal' = a purchase or sale between private people, e.g. on a marketplace." + E19);
const S = "Deep search summary in the 'Report insights' section of a phone lookup report. The page builds the summary from sentence keys depending on the reason the customer picked and what the report contains. ";
const SEC = " 'Profile summary', 'Possible owners', 'Photos' and 'Carrier details' are report section names: use the same translations as the section titles.";
const E22 = " Ticket: REALCHECK-822.";
put(32, T822, S + "BOLD first sentence of the second paragraph, used for every reason when the report has no name. The reason's no_name sentence follows right after it." + E22);
put(33, T822, S + "BOLD first sentence of the second paragraph, used for every reason when the report has exactly one possible owner. Keep [%1$s:name] – a person's name from public records. The reason's name sentence follows right after it." + E22);
put(34, T822, S + "BOLD first sentence of the second paragraph when the report has several possible owners; [%1$s:name] = the first name listed (keep the placeholder). The reason's name sentence and details::names sentence follow." + E22);
put(35, T822, S + "Extra sentence added when the report lists more than one possible owner. 'changed hands' = the number was passed on to a new owner." + SEC + E22);
put(36, T822, S + "Extra sentence added when the report lists more than one possible owner. 'they' = the person the customer is in contact with; 'the name they gave you' = the name that person told the customer." + SEC + E22);
put(37, T822, S + "Extra sentence added when the Photos section has at least one photo (variant for reasons about identifying who uses the number). 'it' = the phone number." + SEC + E22);
put(38, T822, S + "Extra sentence added when the Photos section has at least one photo (variant comparing with the pictures on the person's online profile, e.g. dating or social profile)." + SEC + E22);
put(39, T822, S + "Extra sentence added when the Photos section has at least one photo (variant comparing with the person the customer is dealing with)." + SEC + E22);
put(40, T822, S + "Extra sentence added when the number appears in data breaches (leaks of personal data after a hack). Plural key: # = number of data breaches; fill every plural form your language needs, the whole sentence changes with the number. 'strangers' = unknown people." + E22);
put(41, T822, S + "Extra sentence added when the number appears in data breaches (leaks of personal data after a hack). Plural key: # = number of data breaches; fill every plural form your language needs. 'it' = the number; 'its owner' = the owner of the number." + E22);
const PART = [
 ['opener', "FIRST sentence of the summary: restates why the customer is checking. Every opener ends with 'so we read your report with that in mind' – translate that ending the same way in all 7 openers."],
 ['no_name', "Sentence shown right after the bold sentence 'We couldn't link this number to a name in public sources.' (shared::no_name_bold), in the same paragraph, when the report has no name. 'That'/'So' at the start refers back to that bold sentence, so it must read as its continuation."],
 ['name', "Sentence shown right after the bold sentence 'Public sources link this number to the name …' (shared::name_bold / names_bold), when the report has a name. 'this name'/'that name' = the person's name in that bold sentence."],
 ['context', "Third paragraph: what public data can and can't show for this reason."],
 ['tip_1', "Tip 1 of 3 (bullet list): practical advice to the customer, imperative."],
 ['tip_2', "Tip 2 of 3 (bullet list): practical advice to the customer, imperative."],
 ['tip_3', "Tip 3 of 3 (bullet list): practical advice to the customer."],
 ['closing', "CLOSING line of the summary, shown just before the grey disclaimer."]];
const R = [['caller', "Find out who’s been calling me", 42, ''], ['scam', 'Check if this could be a scam', 50, ''], ['online', 'Check someone I met online', 58, " 'online' = someone the customer met on the internet (dating app, social network)."], ['identity', 'Make sure someone is who they say', 66, ''], ['reconnect', 'Reconnect with someone I lost touch with', 74, " 'reconnect' = get back in touch with someone after a long time."], ['deal', 'Check a buyer or seller before a deal', 82, " 'deal' = a purchase or sale between private people, e.g. on a marketplace."], ['general', 'I just want to know more about this number', 90, '']];
R.forEach(r => PART.forEach((p, i) => {
  const sec = (['context','name','tip_1','tip_2','tip_3'].indexOf(p[0]) !== -1 && (r[0] === 'caller' || r[0] === 'general')) ? SEC : '';
  put(r[2] + i, T822, S + "Reason picked: '" + r[1] + "'. " + p[1] + r[3] + sec + E22);
}));
const C = "Social-proof counter ('N … today') shown as a card with a big number. Plural key: # (inside <num></num>) = the number; fill every plural form your language needs. Keep the tags <line1></line1>, <line2></line2> and <num></num>: line 1 and line 2 are two lines of the card, so the text must split naturally into two lines (you may move words between the lines). One key replaces the old concatenated keys callers_label + identified_today. ";
put(6, TB('REALCHECK-239'), "Phone lookup (reverse phone lookup) funnel – lookup summary page. " + C + "'caller' = a person who called the customer; 'identified' = we found out who it is. Ticket: REALCHECK-239.");
put(3, TB('REALCHECK-239'), "VIN lookup (vehicle history check by VIN) funnel – lookup summary page. " + C + "'VIN lookup' = a check of a vehicle identification number; 'performed' = done. Ticket: REALCHECK-239.");
put(4, TB('REALCHECK-239'), "Image (photo) lookup funnel – lookup summary page. " + C + "'image search' = a reverse search of a photo; 'performed' = done. Ticket: REALCHECK-239.");
put(5, TB('REALCHECK-239'), "Phone location checker funnel – checkout page. " + C + "'location' = a phone's location; 'shared today' = locations that people shared through the service today. Ticket: REALCHECK-239.");
const CS = "VIN lookup landing page – country/region selector next to the VIN input. Short label of the SELECTED value shown in the closed selector (the open list shows the full localized names). Use your language's usual short form or abbreviation and keep it very short (the selector is narrow); keep the code if your language uses it as is. Ticket: REALCHECK-441.";
put(0, TB('REALCHECK-441'), "US = United States. " + CS);
put(1, TB('REALCHECK-441'), "CA = Canada. " + CS);
put(2, TB('REALCHECK-441'), "EU = European Union (a region, not a country). " + CS);
put(98, TB('REALCHECK-460'), "VIN report (vehicle history) – Ownership history section: title of each owner card, e.g. '1st owner', '2nd owner'. position = the owner's number in order (1 = first owner). ICU selectordinal: keep the {position, selectordinal, ...} structure and #, translate the text inside the braces; if your language writes ordinals one way for every number (e.g. '1.' or '1º'), you can keep only other {…}. Make the ordinal agree with the word for 'owner'. Ticket: REALCHECK-460.");
[[99,'length'],[101,'width'],[100,'height']].forEach(d => put(d[0], TB('REALCHECK-444'), "VIN report (vehicle history) – Vehicle specifications section, Dimensions row. [%1$s:value] = the measurement with its unit (e.g. '4.6 m' or '181 in'), keep the placeholder. The word in brackets says which dimension it is: the vehicle's " + d[1] + ". Ticket: REALCHECK-444."));
const F = "VIN report (vehicle history) – Vehicle specifications section, value of the Fuel type row (what the vehicle runs on). Short value, capital first letter as in a table. Ticket: REALCHECK-444.";
[[102,"Gasoline = petrol (use the usual word in your market). "],[103,"Diesel fuel. "],[104,"Electric = battery-electric vehicle (adjective describing the fuel type, not 'electrician'/'electricity bill'). "],[105,"Hybrid = petrol/gasoline + electric hybrid vehicle. "],[106,"Plug-in hybrid = hybrid that can be charged from a socket. "],[107,"Flex fuel = vehicle that can run on gasoline or ethanol blends (FFV). "],[110,"Hydrogen (fuel-cell vehicle). "],[109,"LPG = liquefied petroleum gas (autogas); use your language's usual abbreviation in brackets. "],[108,"CNG = compressed natural gas; use your language's usual abbreviation in brackets. "],[111,"Ethanol (E85) = fuel with up to 85% ethanol; keep 'E85'. "]].forEach(f => put(f[0], TB('REALCHECK-444'), f[1] + F));
const ALL = Object.keys(PLAN).sort();
const ONLY = $('Run Scope').first().json.only || [];
const IDS = ONLY.length ? ONLY : ALL;
return [{ json: { project_id: '964775386a3ce03ecca883.03770715', plan: PLAN, key_ids: IDS } }];

// Guards: skip archived; tags merged (only missing ones); description and ES written ONLY when empty (ES as unverified).
// desc_old/desc_new replaces a description ONLY when the live text is exactly desc_old.
// tr_replace {lang: [old, new]} replaces a target ONLY when the live text is exactly old (written unverified).
const p = $('Params').first().json; const keys = ($input.first().json.keys) || [];
const byId = {}; for (const k of keys) { byId[k.key_id] = k; }
const out = []; const skipped = []; const expected = {}; const expDesc = {}; const expTr = {}; const current = {};
for (const id of p.key_ids) {
  const k = byId[id]; if (!k || k.is_archived) { skipped.push({ id: id, why: 'missing/archived' }); continue; }
  const pl = p.plan[id] || {};
  const item = { key_id: Number(id) };
  const trs = [];
  current[id] = (k.translations || []).map(function (t) { return { lang: t.language_iso, text: t.translation, by: t.modified_by_email, at: t.modified_at }; });
  const missing = (pl.tags || []).filter(function (t) { return (k.tags || []).indexOf(t) === -1; });
  if (missing.length) { item.tags = missing; item.merge_tags = true; }
  if (pl.desc) {
    if (!String(k.description || '').trim()) { item.description = pl.desc; expDesc[id] = pl.desc; }
    else { skipped.push({ id: id, why: 'description not empty - kept' }); }
  }
  if (pl.desc_new) {
    if (k.description === pl.desc_old) { item.description = pl.desc_new; expDesc[id] = pl.desc_new; }
    else { skipped.push({ id: id, why: 'description changed by someone else - kept' }); }
  }
  if (pl.es) {
    const es = (k.translations || []).filter(function (t) { return t.language_iso === 'es'; })[0];
    const cur = es ? String(es.translation || '').trim() : '';
    if (!cur) { trs.push({ language_iso: 'es', translation: pl.es, is_unverified: true }); expected[id] = pl.es; }
    else { skipped.push({ id: id, why: 'es not empty - kept' }); }
  }
  if (pl.tr_replace) {
    for (const lang of Object.keys(pl.tr_replace)) {
      const pair = pl.tr_replace[lang];
      const t = (k.translations || []).filter(function (x) { return x.language_iso === lang; })[0];
      if (t && t.translation === pair[0]) { trs.push({ language_iso: lang, translation: pair[1], is_unverified: true }); expTr[id + ':' + lang] = pair[1]; }
      else { skipped.push({ id: id, lang: lang, why: 'live text differs from expected old - kept', live: t ? t.translation : null }); }
    }
  }
  if (trs.length) { item.translations = trs; }
  if (item.tags || item.translations || item.description) { out.push(item); }
}
if (out.length === 0) { throw new Error('Nothing to write: ' + JSON.stringify(skipped)); }
return [{ json: { body: { keys: out }, skipped: skipped, expected: expected, exp_desc: expDesc, exp_tr: expTr, current: current, plan: out.map(function (x) { return x.key_id; }) } }];

const p = $('Params').first().json; const B = $('Build').first().json;
const byId = {}; for (const it of $input.all()) { for (const k of ((it.json && it.json.keys) || [])) { byId[k.key_id] = k; } }
const res = B.plan.map(function (id) {
  const k = byId[id] || {}; const tags = k.tags || []; const pl = p.plan[String(id)] || {};
  const trs = k.translations || [];
  const es = trs.filter(function (t) { return t.language_iso === 'es'; })[0] || {};
  const okT = (pl.tags || []).every(function (t) { return tags.indexOf(t) !== -1; });
  const exp = B.expected[String(id)]; const okE = !exp || es.translation === exp;
  const expD = (B.exp_desc || {})[String(id)]; const okD = !expD || k.description === expD;
  const trCheck = Object.keys(B.exp_tr || {}).filter(function (x) { return x.split(':')[0] === String(id); }).map(function (x) { const lang = x.split(':')[1]; const t = trs.filter(function (y) { return y.language_iso === lang; })[0] || {}; return { lang: lang, ok: t.translation === B.exp_tr[x], text: t.translation, unverified: t.is_unverified }; });
  const okR = trCheck.every(function (x) { return x.ok; });
  return { id: id, ok: okT && okE && okD && okR, tr: trCheck, tags: tags, description: k.description };
});
const bad = res.filter(function (x) { return !x.ok; });
return [{ json: { ok: bad.length === 0, n: res.length, tr_written: Object.keys(B.exp_tr || {}).length, desc_written: Object.keys(B.exp_desc || {}).length, bad: bad, skipped: B.skipped, sample: res.slice(0, 2) } }];

// Lokalise returned 500 on a 40-key PUT: send 10 keys per call.
const out = [];
for (const it of $input.all()) { const ks = it.json.body.keys; for (let i = 0; i < ks.length; i += 10) { out.push({ json: { body: { keys: ks.slice(i, i + 10) } } }); } }
return out;
